import os, glob, re

# Let's first check the session log to see if there's any log file
d = os.environ.get('RLM_SESSION_DIR', '')
print("Session dir:", d)

# Check if there's a sessions directory
if d:
    import os.path
    print("Trying to find session files...")
    # Look for recent files
    for root, dirs, files in os.walk(d):
        # Only get a few levels deep
        if dirs:
            level = root.count(os.sep) - d.count(os.sep)
            if level <= 2:
                pass
        if 'session' in root.lower() or 'task' in root.lower():
            for fn in files:
                if fn.endswith('.jsonl') or fn.endswith('.py'):
                    print(f"  Found: {os.path.join(root, fn)}")
            break

# Now load the session log
session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
if not os.path.exists(session_file):
    print("Session file not found at:", session_file)
else:
    G = {}
    with open(session_file) as f:
        for msg in f:
            if msg.strip():
                msg_data = eval(msg)
                if 'action_role' in msg_data and msg_data['action_role'] == 'user':
                    print("User action:", msg_data['action'])
                elif msg_data.get('action') in ['submit', 'request_demos', 'finish']:
                    print("Recent action:", msg_data.get('action'), msg_data.get('grid'))
print(f"\nLoaded {len(G)} demo pairs from session log.")

